<?php /** @var array $languages @var array $pages @var int $selectedPage @var string $selectedLocale @var array|null $translation @var \Core\Security\Csrf $csrf */ $source=array_values(array_filter($pages,fn(array $p):bool=>(int)$p['id']===$selectedPage))[0]??null; ?>
<div class="card"><h2 style="margin-top:0">Site languages</h2><form method="post" class="inline-fields"><?= $csrf->field() ?><input type="hidden" name="action" value="language"><div><label>Locale</label><input name="locale" placeholder="fr or es-mx" required></div><div><label>Language name</label><input name="name" placeholder="French" required></div><button class="btn" style="align-self:end">Add language</button></form></div>
<div class="card"><h2 style="margin-top:0">Translate a page</h2><form method="get" class="inline-fields"><div><label>Source page</label><select name="page_id" required><option value="">Choose page</option><?php foreach($pages as $p): ?><option value="<?= (int)$p['id'] ?>" <?= $selectedPage===(int)$p['id']?'selected':'' ?>><?= e($p['title']) ?></option><?php endforeach; ?></select></div><div><label>Language</label><select name="locale" required><option value="">Choose language</option><?php foreach($languages as $language): ?><option value="<?= e_attr($language['locale']) ?>" <?= $selectedLocale===$language['locale']?'selected':'' ?>><?= e($language['name']) ?></option><?php endforeach; ?></select></div><button class="btn secondary" style="align-self:end">Load</button></form></div>
<?php if($source&&$selectedLocale): ?><div class="card"><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="page_id" value="<?= (int)$selectedPage ?>"><input type="hidden" name="locale" value="<?= e_attr($selectedLocale) ?>"><label>Translated title</label><input name="title" value="<?= e_attr($translation['title']??'') ?>" placeholder="<?= e_attr($source['title']) ?>" required><label>Translated slug</label><input name="slug" value="<?= e_attr($translation['slug']??'') ?>" placeholder="translated-page" required><label>Translated body</label><textarea name="body" rows="8"><?= e($translation['body']??$source['body']??'') ?></textarea><label>Translated blocks JSON</label><textarea name="blocks_json" rows="8"><?= e($translation['blocks_json']??$source['blocks_json']??'[]') ?></textarea><label>Meta title</label><input name="meta_title" value="<?= e_attr($translation['meta_title']??'') ?>"><label>Meta description</label><textarea name="meta_description"><?= e($translation['meta_description']??'') ?></textarea><input type="hidden" name="schema_json" value="<?= e_attr($translation['schema_json']??$source['schema_json']??'') ?>"><button class="btn">Save translation</button></form></div><?php endif; ?>
